import {probeRejectionMessage} from './rejectionMessage.js';

describe('rejection messages [specs/hal-engine-config-hooks/spec.md#9]', () => {
  it('reports failed string conversion without replacing the rejected value', () => {
    const conversionError = new Error('conversion failed');
    const rejected = {
      toString() {
        throw conversionError;
      },
    };

    expect(probeRejectionMessage(rejected)).toEqual({ok: false, error: conversionError});
  });
});
EOF
timeout 300 npm test -- --runTestsByPath src/orchestration/rejectionMessage.test.ts --runInBand"

/usr/bin/zsh -lc "cd /var/tmp/loop-bench/runs/cab45f99045f/workspace/target && cat > src/orchestration/rejectionMessage.ts <<'EOF'
export function probeRejectionMessage(value: unknown): {ok: true; value: string} | {ok: false; error: unknown} {
  try {
    return {ok: true, value: String(value)};
  } catch (error) {
    return {ok: false, error};
  }
}
EOF
